:root {
  --color-bg: #F4F6F9;
  --color-surface: #FFFFFF;
  --color-surface-muted: #EEF1F5;
  --color-border: #D3DAE4;
  --color-border-strong: #8895A7;
  --color-text: #1A2433;
  --color-text-muted: #475467;
  --color-text-inverse: #FFFFFF;
  --color-nav-bg: #13243A;
  --color-nav-text: #E8EEF6;
  --color-nav-active-bg: #0B6E6E;
  --color-primary: #0B6E6E;
  --color-primary-hover: #085757;
  --color-primary-soft: #E1F2F1;
  --color-focus: #0B5FFF;
  --color-success: #14653A;
  --color-success-bg: #E2F4E9;
  --color-danger: #A4231F;
  --color-danger-bg: #FCE8E6;
  --color-warning: #7A4300;
  --color-warning-bg: #FFF0D2;
  --color-info: #1B4B9E;
  --color-info-bg: #E3ECFB;
  --color-status-waiting: #7A4300;
  --color-status-waiting-bg: #FFF0D2;
  --color-status-called: #1B4B9E;
  --color-status-called-bg: #E3ECFB;
  --color-status-serving: #58299F;
  --color-status-serving-bg: #EEE7FA;
  --color-status-completed: #14653A;
  --color-status-completed-bg: #E2F4E9;
  --color-status-cancelled: #475467;
  --color-status-cancelled-bg: #E6EAF0;
  --color-status-no-show: #963210;
  --color-status-no-show-bg: #FFE9DA;

  --font-family: system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --font-size-xs: 0.75rem;
  --font-size-sm: 0.875rem;
  --font-size-md: 1rem;
  --font-size-lg: 1.25rem;
  --font-size-xl: 1.5rem;
  --font-size-2xl: 2rem;
  --font-size-display: clamp(3rem, 9vw, 7rem);
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;
  --line-height: 1.5;
  --line-height-tight: 1.2;

  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
  --space-7: 48px;

  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-pill: 999px;

  --shadow-card: 0 1px 2px rgba(19, 36, 58, 0.08), 0 1px 3px rgba(19, 36, 58, 0.06);
  --shadow-raised: 0 8px 24px rgba(19, 36, 58, 0.16);

  --width-content: 1200px;
  --width-form: 640px;
  --width-sidebar: 232px;
  --width-dialog: 520px;

  --control-height: 44px;
  --control-height-sm: 36px;
  --control-min-target: 44px;

  --breakpoint-sm: 480px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 1024px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--font-family);
  font-size: var(--font-size-md);
  line-height: var(--line-height);
  background: var(--color-bg);
  color: var(--color-text);
}

img {
  max-width: 100%;
  height: auto;
}

:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}

